        // MARK: - Sharing & Import
        "About Export Formats": [.japanese: "出力形式について", .english: "About Export Formats", .german: "Exportformate", .french: "Formats d'export", .spanish: "Formatos de exportación", .italian: "Formati di esportazione", .chineseSimplified: "导出格式说明", .korean: "내보내기 형식 안내"],
        "rowpilot_desc": [.japanese: "【.rowpilot形式】\nRowPilotアプリ間で完全なデータを共有するための専用形式です。グラフ用の時系列データ（ストロークごとの情報）や位置情報、クルー情報などが全て含まれます。他の端末のRowPilotアプリへデータ移行・インポートしたい場合に選択してください。", .english: "[.rowpilot format]\nA proprietary format for sharing complete data between RowPilot apps. It includes all time-series data for graphs (stroke-by-stroke info), location data, and crew details. Choose this if you want to import/transfer data to RowPilot on another device.", .german: "[.rowpilot Format]\nEigenformat für vollständige Datenfreigabe zwischen RowPilot-Apps.", .french: "[Format .rowpilot]\nFormat propriétaire pour partager toutes les données entre apps RowPilot.", .spanish: "[Formato .rowpilot]\nFormato propietario para compartir datos completos entre apps RowPilot.", .italian: "[Formato .rowpilot]\nFormato proprietario per condividere dati completi tra le app RowPilot.", .chineseSimplified: "【.rowpilot格式】\nRowPilot应用间共享完整数据的专用格式。", .korean: "[.rowpilot 형식]\nRowPilot 앱 간 완전한 데이터를 공유하기 위한 전용 형식입니다."],
        "csv_desc": [.japanese: "【.csv形式 (RowPilot MAX限定)】\nExcelやGoogleスプレッドシートなどの表計算ソフトで管理するための一般的な形式です。日付、時間、距離、平均ペース、平均SPM、デバイス情報、メモなどのサマリーのみが保存されます。PC等で複数の練習データを一覧化して管理したい場合に適しています。", .english: "[.csv format (RowPilot MAX only)]\nA standard format for managing data in spreadsheets like Excel or Google Sheets. It saves only the workout summary (date, duration, distance, average pace, SPM, device info, and notes). Best for logging and tracking multiple records on a computer.", .german: "[.csv Format (nur MAX)]\nStandardformat für Tabellenkalkulationen. Nur Zusammenfassung.", .french: "[Format .csv (MAX uniquement)]\nFormat standard pour tableurs. Résumé uniquement.", .spanish: "[Formato .csv (solo MAX)]\nFormato estándar para hojas de cálculo. Solo resumen.", .italian: "[Formato .csv (solo MAX)]\nFormato standard per fogli di calcolo. Solo riepilogo.", .chineseSimplified: "【.csv格式 (仅限RowPilot MAX)】\n用于Excel等电子表格的通用格式。仅保存摘要。", .korean: "[.csv 형식 (RowPilot MAX 전용)]\nExcel 등 스프레드시트용 범용 형식. 요약만 저장됩니다."],
        "Share RowPilot Data (.rowpilot)": [.japanese: "RowPilotデータとして共有 (.rowpilot)", .english: "Share RowPilot Data (.rowpilot)", .german: "RowPilot-Daten teilen (.rowpilot)", .french: "Partager données RowPilot (.rowpilot)", .spanish: "Compartir datos RowPilot (.rowpilot)", .italian: "Condividi dati RowPilot (.rowpilot)", .chineseSimplified: "共享RowPilot数据 (.rowpilot)", .korean: "RowPilot 데이터 공유 (.rowpilot)"],
        "Export CSV (.csv)": [.japanese: "CSV形式でエクスポート (.csv)", .english: "Export CSV (.csv)", .german: "CSV exportieren (.csv)", .french: "Exporter CSV (.csv)", .spanish: "Exportar CSV (.csv)", .italian: "Esporta CSV (.csv)", .chineseSimplified: "导出CSV (.csv)", .korean: "CSV 내보내기 (.csv)"],
